  const origFetch = window.fetch;
  window.fetch = async function(resource, init) {
    const url = typeof resource === 'string' ? resource : (resource && resource.url ? resource.url : '');
    const cleanUrl = url.split('?')[0];

    // Check if intercepted
    if (MOCK_DATA[cleanUrl] || MOCK_DATA[decodeURIComponent(cleanUrl)]) {
      const data = MOCK_DATA[cleanUrl] || MOCK_DATA[decodeURIComponent(cleanUrl)];
      return new Response(JSON.stringify(data), {
        status: 200,
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    if (cleanUrl.startsWith('/api/gms/sub-sequences/')) {
      const parts = cleanUrl.split('/api/gms/sub-sequences/');
      const subSeqId = decodeURIComponent(parts[1] || '').trim();
      const mockKey = `/api/gms/sub-sequences/${subSeqId}`;
      if (MOCK_DATA[mockKey]) {
        return new Response(JSON.stringify({ ok: true, ...MOCK_DATA[mockKey] }), {
          status: 200, headers: { 'Content-Type': 'application/json; charset=utf-8' }
        });
      }
      try {
        const localRes = await origFetch(`data/gmsSubSequences/${subSeqId}.json`);
        if (localRes.ok) {
          const localData = await localRes.json();
          return new Response(JSON.stringify({ ok: true, ...localData }), {
            status: 200, headers: { 'Content-Type': 'application/json; charset=utf-8' }
          });
        }
      } catch (e) {}
    }

    if (cleanUrl === '/api/gms/maintenance-mode') {
      return new Response(JSON.stringify({ ok: true, pm: false, setup: false }), {
        status: 200, headers: { 'Content-Type': 'application/json' }
      });
    }

    if (cleanUrl === '/api/gms/status') {
      return new Response(JSON.stringify({ ok: true, status: 'running', intervalMs: 1000, values: {}, pts: {} }), {
        status: 200, headers: { 'Content-Type': 'application/json' }
      });
    }

    if (cleanUrl.startsWith('/api/gms/valve/write') || cleanUrl.startsWith('/api/gms/worklog')) {
      return new Response(JSON.stringify({ ok: true }), {
        status: 200, headers: { 'Content-Type': 'application/json' }
      });
    }

    if (cleanUrl.startsWith('/api/gms/valves')) {
      return new Response(JSON.stringify({ ok: true, valves: [] }), {
        status: 200, headers: { 'Content-Type': 'application/json' }
      });
    }

    // Fallback to original fetch
    try {
      return await origFetch.apply(this, arguments);
    } catch (e) {
      if (typeof url === 'string' && (url.endsWith('.html') || url.endsWith('.svg') || url.endsWith('.css') || url.includes('.html?'))) {
        return new Response(`<!DOCTYPE html><html><body>Error loading ${url}: ${e.message}</body></html>`, {
          status: 404, headers: { 'Content-Type': 'text/html' }
        });
      }
      // Offline fallback for API
      return new Response(JSON.stringify({ ok: true }), {
        status: 200, headers: { 'Content-Type': 'application/json' }
      });
    }
  };
